import operator
import re
import sys
import threading

_DIV0 = "#DIV/0!"
_CYCLE = "#CYCLE!"
_TOKEN_RE = re.compile(r"\d+|[A-Z]+\d*|<>|<=|>=|[-+*/(),:=<>]")
_CELL_RE = re.compile(r"([A-Z])(\d+)")
_INT_RE = re.compile(r"-?\d+")
_FUNCS = ("SUM", "MIN", "MAX", "IF")
_CMP_OPS = {
    "=": operator.eq,
    "<>": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


def _is_cell(tok):
    return _CELL_RE.fullmatch(tok) is not None


def _tokenize(formula):
    text = re.sub(r"\s+", "", formula)
    return _TOKEN_RE.findall(text)


# ---- Parser: each function returns (node, next_index) ----

def _parse_formula(toks, i):
    node, i = _parse_term(toks, i)
    while i < len(toks) and toks[i] in ("+", "-"):
        op = toks[i]
        right, i = _parse_term(toks, i + 1)
        node = ("bin", op, node, right)
    return node, i


def _parse_term(toks, i):
    node, i = _parse_unary(toks, i)
    while i < len(toks) and toks[i] in ("*", "/"):
        op = toks[i]
        right, i = _parse_unary(toks, i + 1)
        node = ("bin", op, node, right)
    return node, i


def _parse_unary(toks, i):
    if toks[i] == "-":
        node, i = _parse_unary(toks, i + 1)
        return ("neg", node), i
    return _parse_atom(toks, i)


def _parse_atom(toks, i):
    t = toks[i]
    if t == "(":
        node, i = _parse_formula(toks, i + 1)
        return node, i + 1  # skip ')'
    if t.isdigit():
        return ("num", int(t)), i + 1
    if t in _FUNCS and i + 1 < len(toks) and toks[i + 1] == "(":
        return _parse_call(toks, i)
    if _is_cell(t):
        return ("ref", t), i + 1
    raise ValueError("unexpected token: " + t)


def _parse_call(toks, i):
    name = toks[i]
    i += 2  # skip name and '('
    if name == "IF":
        left, i = _parse_formula(toks, i)
        op = toks[i]
        right, i = _parse_formula(toks, i + 1)
        then_node, i = _parse_formula(toks, i + 1)   # skip ','
        else_node, i = _parse_formula(toks, i + 1)   # skip ','
        return ("if", left, op, right, then_node, else_node), i + 1  # skip ')'

    args = []
    while True:
        if _is_cell(toks[i]) and toks[i + 1] == ":":
            args.append(("range", toks[i], toks[i + 2]))
            i += 3
        else:
            node, i = _parse_formula(toks, i)
            args.append(node)
        if toks[i] == ",":
            i += 1
            continue
        i += 1  # skip ')'
        break
    return ("call", name, args), i


# ---- Evaluation ----

def _cells_in_range(a, b):
    ca, ra = _CELL_RE.fullmatch(a).groups()
    cb, rb = _CELL_RE.fullmatch(b).groups()
    c_lo, c_hi = sorted((ord(ca) - 65, ord(cb) - 65))
    r_lo, r_hi = sorted((int(ra), int(rb)))
    for r in range(r_lo, r_hi + 1):
        for c in range(c_lo, c_hi + 1):
            yield f"{chr(65 + c)}{r}"


def _get(name, ctx):
    raw = ctx["raw"]
    if name not in raw:
        return 0
    memo = ctx["memo"]
    if name in memo:
        return memo[name]
    if name in ctx["active"]:
        return _CYCLE
    ctx["active"].add(name)
    value = _eval_cell(raw[name], ctx)
    ctx["active"].discard(name)
    memo[name] = value
    return value


def _eval_cell(content, ctx):
    content = content.strip()
    if _INT_RE.fullmatch(content):
        return int(content)
    toks = _tokenize(content[1:])  # drop leading '='
    node, _ = _parse_formula(toks, 0)
    return _eval(node, ctx)


def _eval(node, ctx):
    kind = node[0]

    if kind == "num":
        return node[1]

    if kind == "ref":
        return _get(node[1], ctx)

    if kind == "neg":
        v = _eval(node[1], ctx)
        if isinstance(v, str):
            return v
        return -v

    if kind == "bin":
        op = node[1]
        left = _eval(node[2], ctx)
        if isinstance(left, str):
            return left
        right = _eval(node[3], ctx)
        if isinstance(right, str):
            return right
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        # "/" : truncate toward zero
        if right == 0:
            return _DIV0
        q = abs(left) // abs(right)
        return q if (left < 0) == (right < 0) else -q

    if kind == "call":
        name, args = node[1], node[2]
        values = []
        for arg in args:
            if arg[0] == "range":
                for cell in _cells_in_range(arg[1], arg[2]):
                    if cell not in ctx["raw"]:
                        continue
                    v = _get(cell, ctx)
                    if isinstance(v, str):
                        return v
                    values.append(v)
            else:
                v = _eval(arg, ctx)
                if isinstance(v, str):
                    return v
                values.append(v)
        if name == "SUM":
            return sum(values)
        if not values:
            return 0
        return min(values) if name == "MIN" else max(values)

    if kind == "if":
        left = _eval(node[1], ctx)
        if isinstance(left, str):
            return left
        right = _eval(node[3], ctx)
        if isinstance(right, str):
            return right
        if _CMP_OPS[node[2]](left, right):
            return _eval(node[4], ctx)
        return _eval(node[5], ctx)

    raise ValueError("unknown node: " + kind)


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    ctx = {"raw": cells, "memo": {}, "active": set()}
    result = {}

    def run():
        for name in cells:
            result[name] = _get(name, ctx)

    # Dependency chains can be up to every cell deep, so use a deep stack.
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 200000))
    try:
        threading.stack_size(512 * 1024 * 1024)
    except (ValueError, RuntimeError):
        pass
    worker = threading.Thread(target=run)
    worker.start()
    worker.join()

    return {name: result[name] for name in cells}
